/** Where the hops grow: USDA NASS acreage for Washington, Oregon and Idaho.
 *  data/acreage/usda-nass.yml is generated by tools/ingest/usda_nass.py from
 *  the saved National Hop Reports; nothing here is typed in by hand. */

import { esc, shell, footer } from './render.js';

export const STATES = [
  { key: 'WA', label: 'Washington', color: '#2a78d6' },
  { key: 'OR', label: 'Oregon', color: '#eb6834' },
  { key: 'ID', label: 'Idaho', color: '#1baf7a' },
];
const STATE = Object.fromEntries(STATES.map((s) => [s.key, s]));
const BUCKETS = new Set(['Experimental', 'Other varieties']);

const n0 = (v) => (typeof v === 'number' ? Math.round(v).toLocaleString('en-US') : v === 'withheld' ? 'withheld' : '—');
const isNum = (v) => typeof v === 'number';

// ------------------------------------------------------------------ joining

/** Everything the site and API need about one hop's acreage, or null.
 *  A hop can sit in more than one NASS row over time (Columbus was
 *  "Columbus/Tomahawk" until 2019, then "CTZ"), so its rows are merged by
 *  year -- the generator guarantees they never overlap. */
export function acreageFor(slug, acreage) {
  if (!acreage) return null;
  const entries = acreage.varieties.filter((v) => v.slugs.includes(slug));
  if (!entries.length) return null;

  const series = { acres: {}, production_klb: {} };
  for (const measure of Object.keys(series)) {
    for (const st of STATES.map((s) => s.key)) {
      const merged = Object.assign({}, ...entries.map((e) => e[measure]?.[st] ?? {}));
      if (Object.keys(merged).length) series[measure][st] = merged;
    }
  }

  const notes = entries
    .map((e) => {
      const years = Object.values(e.acres ?? {}).flatMap((s) => Object.keys(s).map(Number));
      const span = years.length ? `${Math.min(...years)}–${Math.max(...years)}` : '';
      if (e.slugs.length > 1) return `${span}: counted in “${e.name}”, one figure NASS reports for ${e.slugs.length} cultivars together`;
      const others = (e.reported_as ?? []).filter((r) => r !== e.name);
      return others.length ? `${span}: NASS reports it as “${others.join('” / “')}”` : null;
    })
    .filter(Boolean);

  const latest = acreage.years.at(-1);
  const rank = {};
  for (const { key } of STATES) {
    const mine = series.acres[key]?.[latest];
    if (!isNum(mine)) continue;
    const others = acreage.varieties
      .filter((v) => !BUCKETS.has(v.name))
      .map((v) => v.acres?.[key]?.[latest])
      .filter(isNum);
    rank[key] = others.filter((v) => v > mine).length + 1;
  }

  return {
    source: acreage.source,
    latest,
    shared: entries.some((e) => e.slugs.length > 1),
    notes,
    acres: series.acres,
    production_klb: series.production_klb,
    rank,
  };
}

// -------------------------------------------------------------- line chart

/** Small multi-series line chart, SVG, rendered at build time. Hover is
 *  handled by assets/grown.js reading the data-* attributes. Gaps (withheld
 *  or unreported years) break the line rather than being bridged. */
export function lineChart({ id, series, years, height = 300, title, desc, unit = 'acres' }) {
  const W = 720;
  const M = { top: 16, right: 104, bottom: 34, left: 58 };
  const PW = W - M.left - M.right;
  const PH = height - M.top - M.bottom;

  const all = series.flatMap((s) => years.map((y) => s.values[y]).filter(isNum));
  const rawMax = Math.max(...all, 1);
  const step = niceStep(rawMax / 4);
  const yMax = Math.ceil(rawMax / step) * step;

  const sx = (y) => M.left + ((y - years[0]) / Math.max(1, years.at(-1) - years[0])) * PW;
  const sy = (v) => M.top + PH - (v / yMax) * PH;

  const yTicks = [];
  for (let v = 0; v <= yMax + 1e-9; v += step) yTicks.push(v);
  const grid = yTicks
    .map((v) => `<line class="grid" x1="${M.left}" x2="${M.left + PW}" y1="${sy(v).toFixed(1)}" y2="${sy(v).toFixed(1)}"/>
      <text class="tick" x="${M.left - 8}" y="${(sy(v) + 4).toFixed(1)}" text-anchor="end">${short(v)}</text>`)
    .join('');
  const xTicks = years
    .filter((y, i) => years.length <= 6 || i % 2 === (years.length - 1) % 2)
    .map((y) => `<text class="tick" x="${sx(y).toFixed(1)}" y="${M.top + PH + 20}" text-anchor="middle">${y}</text>`)
    .join('');

  const lines = series
    .map((s) => {
      const segments = [];
      let current = [];
      for (const y of years) {
        const v = s.values[y];
        if (isNum(v)) current.push(`${sx(y).toFixed(1)},${sy(v).toFixed(1)}`);
        else if (current.length) (segments.push(current), (current = []));
      }
      if (current.length) segments.push(current);
      const paths = segments
        .map((pts) =>
          pts.length === 1
            ? `<circle class="dot" cx="${pts[0].split(',')[0]}" cy="${pts[0].split(',')[1]}" r="4" style="--mark:${s.color}"/>`
            : `<polyline class="ln" points="${pts.join(' ')}" style="--mark:${s.color}"/>`
        )
        .join('');
      return `<g class="series" data-key="${s.key}">${paths}</g>`;
    })
    .join('\n');

  // Direct labels at each line's last real point, nudged apart so they never
  // sit on top of one another.
  const ends = series
    .map((s) => {
      const last = [...years].reverse().find((y) => isNum(s.values[y]));
      return last == null ? null : { s, y: sy(s.values[last]), x: sx(last) };
    })
    .filter(Boolean)
    .sort((a, b) => a.y - b.y);
  for (let i = 1; i < ends.length; i++) if (ends[i].y - ends[i - 1].y < 15) ends[i].y = ends[i - 1].y + 15;
  const labels = ends
    .map(({ s, x, y }) => `<circle class="end" cx="${x.toFixed(1)}" cy="${sy(s.values[[...years].reverse().find((yy) => isNum(s.values[yy]))]).toFixed(1)}" r="4" style="--mark:${s.color}"/>
      <text class="lbl" x="${(M.left + PW + 10).toFixed(1)}" y="${(y + 4).toFixed(1)}">${esc(s.label)}</text>`)
    .join('');

  const data = JSON.stringify({
    unit,
    years,
    x: years.map((y) => +sx(y).toFixed(1)),
    series: series.map((s) => ({ label: s.label, color: s.color, values: years.map((y) => s.values[y] ?? null) })),
  });

  return `<figure class="chart line-chart" data-chart='${esc(data)}'>
    <svg id="${id}" viewBox="0 0 ${W} ${height}" role="img" aria-labelledby="${id}-t ${id}-d">
      <title id="${id}-t">${esc(title)}</title>
      <desc id="${id}-d">${esc(desc)}</desc>
      ${grid}
      <line class="axis" x1="${M.left}" x2="${M.left + PW}" y1="${M.top + PH}" y2="${M.top + PH}"/>
      ${xTicks}
      <line class="cross" x1="0" x2="0" y1="${M.top}" y2="${M.top + PH}" hidden/>
      ${lines}
      ${labels}
      <rect class="hover-zone" x="${M.left - 10}" y="${M.top}" width="${PW + 20}" height="${PH}"/>
    </svg>
    <div class="tip" role="status" hidden></div>
  </figure>`;
}

function niceStep(raw) {
  const mag = 10 ** Math.floor(Math.log10(raw));
  for (const m of [1, 2, 2.5, 5, 10]) if (m * mag >= raw) return m * mag;
  return 10 * mag;
}
const short = (v) => (v >= 1000 ? `${(v / 1000).toLocaleString('en-US', { maximumFractionDigits: 1 })}k` : String(v));

// ----------------------------------------------------------- the hop page

export function hopAcreageBlock(hop, base) {
  const a = hop.acreage;
  if (!a) return '';
  const y = a.latest;
  const present = STATES.filter((s) => a.acres[s.key]);
  if (!present.length) return '';

  const now = present
    .map((s) => ({ s, v: a.acres[s.key][y] }))
    .filter(({ v }) => v != null && v !== 0);
  const numeric = now.filter(({ v }) => isNum(v));
  const total = numeric.reduce((t, { v }) => t + v, 0);
  const withheld = now.some(({ v }) => v === 'withheld');

  let lead;
  if (!now.length) {
    const lastYear = Math.max(...present.flatMap((s) => Object.keys(a.acres[s.key]).map(Number)));
    lead = `Not in the ${y} survey. Last reported in <b>${lastYear}</b>.`;
  } else {
    const parts = now.map(({ s, v }) => `<b class="num">${n0(v)}</b>${isNum(v) ? ' acres' : ''} in ${s.label}`);
    const rankBits = present
      .filter((s) => a.rank[s.key] && a.rank[s.key] <= 10)
      .map((s) => `No. ${a.rank[s.key]} by acreage in ${s.label}`);
    lead = `In ${y}${a.shared ? ', for the shared bucket' : ''}: ${parts.join(', ')}${withheld ? ' (NASS withholds a figure when it would identify a single farm)' : ''}.${
      total && !a.shared ? ` That's ${withheld ? 'at least ' : ''}<b class="num">${n0(total)}</b> acres.` : ''
    }${rankBits.length ? ` ${rankBits.join('; ')}.` : ''}`;
  }

  const years = hop.acreageYears;
  const chart = lineChart({
    id: `grown-${hop.slug}`,
    series: present.map((s) => ({ key: s.key, label: s.label, color: s.color, values: a.acres[s.key] })),
    years,
    height: 240,
    title: `${hop.name}: acres harvested by state, ${years[0]}–${years.at(-1)}`,
    desc: `Line chart of acres harvested in ${present.map((s) => s.label).join(', ')}. The same figures are in the table below.`,
  });

  const rows = years
    .map((yr) => `<tr><td class="num">${yr}</td>${present.map((s) => `<td class="num">${n0(a.acres[s.key][yr])}</td>`).join('')}</tr>`)
    .join('');

  return `<section class="block grown">
    <h2>Where it's grown</h2>
    <p>${lead}</p>
    ${chart}
    ${a.notes.length ? `<p class="fine">${a.notes.map(esc).join('. ')}.</p>` : ''}
    <details class="as-table"><summary>Acres by year</summary>
      <table><thead><tr><th>Year</th>${present.map((s) => `<th>${s.label}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table>
    </details>
    <p class="fine">Acres harvested, from the USDA NASS National Hop Report.
    <a href="${base}grown/">Where America's hops grow →</a></p>
  </section>`;
}

// ------------------------------------------------------------ the /grown/ page

export function renderGrown({ acreage, hops, meta }) {
  const base = '../';
  const years = acreage.years;
  const y = years.at(-1);
  const five = y - 5;
  const US = acreage.states.US;
  const linked = new Set(hops.map((h) => h.slug));
  const nameLink = (v) => {
    const slug = v.slugs.length === 1 && linked.has(v.slugs[0]) ? v.slugs[0] : null;
    return slug ? `<a href="${base}hops/${slug}/">${esc(v.name)}</a>` : esc(v.name);
  };

  const share = (k) => Math.round((acreage.states[k].acres[y] / US.acres[y]) * 100);
  const stats = STATES.map(
    (s) => `<div class="stat" style="--mark:${s.color}">
      <span class="stat-k">${s.label}</span>
      <b class="num">${n0(acreage.states[s.key].acres[y])}</b>
      <span>acres, <b class="num">${share(s.key)}%</b> of the US crop</span>
      <span class="stat-sub num">$${Math.round(acreage.states[s.key].value_kusd[y] / 1000)}M · ${n0(acreage.states[s.key].production_klb[y] / 1000)}M lb</span>
    </div>`
  ).join('');

  const stateChart = lineChart({
    id: 'grown-states',
    series: STATES.map((s) => ({ key: s.key, label: s.label, color: s.color, values: acreage.states[s.key].acres })),
    years,
    height: 320,
    title: `Hop acres harvested by state, ${years[0]}–${y}`,
    desc: `Line chart of acres harvested in Washington, Oregon and Idaho each year. Washington peaked at ${n0(Math.max(...Object.values(acreage.states.WA.acres)))} acres.`,
  });

  const topBars = (st) => {
    const ranked = acreage.varieties
      .filter((v) => !BUCKETS.has(v.name) && isNum(v.acres?.[st]?.[y]) && v.acres[st][y] > 0)
      .sort((p, q) => q.acres[st][y] - p.acres[st][y])
      .slice(0, 12);
    const max = ranked[0]?.acres[st][y] ?? 1;
    const color = STATE[st].color;
    return `<ol class="bars" aria-label="Top varieties by acreage in ${STATE[st].label}, ${y}">
      ${ranked
        .map((v) => {
          const now = v.acres[st][y];
          const then = v.acres[st][five];
          const delta = isNum(then) && then > 0 ? Math.round(((now - then) / then) * 100) : null;
          const deltaText = delta != null ? `${delta > 0 ? '+' : ''}${delta}%` : then === 'withheld' ? '—' : 'new';
          const deltaTitle = then === 'withheld' ? `${five} figure withheld by NASS` : `Change since ${five}`;
          return `<li><span class="bar-name">${nameLink(v)}</span>
          <span class="bar-track"><span class="bar-fill" style="width:${((now / max) * 100).toFixed(1)}%;--mark:${color}"></span></span>
          <span class="bar-val num">${n0(now)}</span>
          <span class="bar-delta num" title="${deltaTitle}">${deltaText}</span></li>`;
        })
        .join('\n      ')}
    </ol>`;
  };

  const rows = acreage.varieties
    .filter((v) => STATES.some((s) => v.acres?.[s.key]?.[y] != null))
    .sort((p, q) => {
      const t = (v) => STATES.reduce((sum, s) => sum + (isNum(v.acres?.[s.key]?.[y]) ? v.acres[s.key][y] : 0), 0);
      return BUCKETS.has(p.name) - BUCKETS.has(q.name) || t(q) - t(p);
    })
    .map(
      (v) => `<tr><td>${nameLink(v)}</td>${STATES.map((s) => `<td class="num">${n0(v.acres?.[s.key]?.[y])}</td>`).join('')}
        <td class="num">${n0(v.acres?.WA?.[five])}</td></tr>`
    )
    .join('\n        ');

  const peak = Object.entries(acreage.states.WA.acres).sort((a, b) => b[1] - a[1])[0];

  const body = `
<header class="masthead" style="padding-top:1.5rem">
  <div class="wrap">
    <nav class="nav" style="border-top:0;padding-top:0">
      <a href="https://brooksgroves.com/">&larr; brooksgroves.com</a>
      <a href="${base}">All varieties</a>
      <a href="${base}landscape/">Hop landscape</a>
      <a href="${base}api/v1/acreage.json">This data as JSON</a>
    </nav>
    <h1 class="page-title">Where America's hops grow</h1>
    <p class="standfirst">Three-quarters of the American hop crop comes out of
    Washington, most of it from the Yakima Valley, with Oregon's Willamette Valley
    and Idaho making up the rest. Here's every variety USDA counts, by state,
    ${years[0]} to ${y}.</p>
  </div>
</header>

<main id="main" class="wrap grown-page">
  <div class="stats">${stats}</div>

  <section class="block">
    <h2>Acres in the ground</h2>
    <p>Washington ran up to <b class="num">${n0(peak[1])}</b> acres in ${peak[0]} on the
    back of the craft boom, and has since pulled back to <b class="num">${n0(acreage.states.WA.acres[y])}</b>.
    Oregon and Idaho followed the same curve.</p>
    ${stateChart}
  </section>

  <div class="cols">
    <section class="block">
      <h2>Washington's top varieties, ${y}</h2>
      <p class="fine">Acres harvested, and change since ${five}.</p>
      ${topBars('WA')}
    </section>
    <section class="block">
      <h2>Oregon's top varieties, ${y}</h2>
      <p class="fine">Acres harvested, and change since ${five}.</p>
      ${topBars('OR')}
      <h2 style="margin-top:2rem">Idaho's top varieties, ${y}</h2>
      ${topBars('ID')}
    </section>
  </div>

  <details class="as-table">
    <summary>Every variety, ${y}</summary>
    <table>
      <thead><tr><th>Variety</th>${STATES.map((s) => `<th>${s.label}</th>`).join('')}<th>Washington, ${five}</th></tr></thead>
      <tbody>
        ${rows}
      </tbody>
    </table>
  </details>

  <p class="fine sourcing">Source: USDA National Agricultural Statistics Service,
  National Hop Report, ${years[0]}–${y} editions, parsed from the plain-text releases
  saved in the repo. Each year comes from the most recent report that covers it,
  since NASS revises the prior two years. “Withheld” means NASS kept the figure back
  to avoid identifying a single farm; those acres are counted in “Other varieties”.
  Columbus, Tomahawk and Zeus are reported as one bucket (CTZ) from 2020.</p>
</main>
${footer(base, meta)}
<script src="${base}assets/grown.js" type="module"></script>`;

  return shell({
    title: "Where America's hops grow — Washington, Oregon and Idaho acreage by variety | HopLore",
    description: `Washington grew ${share('WA')}% of US hops in ${y}. Acres by variety and state from USDA NASS, ${years[0]}–${y}.`,
    body,
    base,
  });
}
